const musicButton=document.querySelector('.headphone-control'),deck=document.querySelector('.turntable'),deckPower=document.querySelector('.deck-power');
let embedController=null,apiPromise=null,generation=0,currentURI='',lastTitle='',titleRequest=null,playbackMode='off';const titles=new Map();
function showState(mode){playbackMode=mode;const moving=mode==='playing';if(deck){deck.classList.toggle('is-playing',moving);deck.setAttribute('aria-label',`Record player. Music is ${mode}.`)}const status=document.querySelector('.playback-status');if(status)status.textContent={playing:'now playing',paused:'paused',buffering:'buffering',off:'music is off',ready:'ready when you are',error:'player unavailable'}[mode];if(deckPower){deckPower.lastChild.textContent=moving?'pause':mode==='paused'?'resume':'listen';deckPower.setAttribute('aria-label',moving?'Pause music':mode==='paused'?'Resume music':'Open music player')}musicButton.classList.toggle('playing',moving);const label=moving?'turn off music':musicPanel.hidden?'turn on music':'close music player';musicButton.setAttribute('aria-label',label);musicButton.querySelector('.headphone-music-prompt').textContent=label}
async function trackTitle(uri){if(!/^spotify:track:[a-zA-Z0-9]{22}$/.test(uri))return;if(uri===currentURI)return;currentURI=uri;lastTitle='';const el=document.querySelector('.track-title');if(el)el.textContent='finding the track…';titleRequest?.abort();titleRequest=new AbortController();const request=titleRequest;const timeout=setTimeout(()=>request.abort(),8000);try{let title=titles.get(uri);if(!title){const url='https://open.spotify.com/track/'+uri.split(':')[2];const r=await fetch('https://open.spotify.com/oembed?url='+encodeURIComponent(url),{signal:request.signal});if(!r.ok)throw Error('metadata unavailable');const data=await r.json();if(typeof data.title!=='string'||!data.title)throw Error('missing title');title=data.title;titles.set(uri,title)}if(currentURI===uri&&!musicPanel.hidden){lastTitle=title;if(el)el.textContent=title}}catch{if(currentURI===uri&&!musicPanel.hidden&&el)el.textContent='track title available in spotify'}finally{clearTimeout(timeout)}}
function getSpotifyAPI(){if(apiPromise)return apiPromise;apiPromise=new Promise((resolve,reject)=>{let settled=false;const timeout=setTimeout(()=>{if(!settled){settled=true;apiPromise=null;reject(Error('Spotify took too long to load'))}},15000);window.onSpotifyIframeApiReady=api=>{if(settled)return;settled=true;clearTimeout(timeout);resolve(api)};const script=document.createElement('script');script.src='https://open.spotify.com/embed/iframe-api/v1';script.async=true;script.onerror=()=>{if(settled)return;settled=true;clearTimeout(timeout);apiPromise=null;script.remove();reject(Error('Spotify could not load'))};document.head.appendChild(script)});return apiPromise}
function closeMusic(){generation++;embedController?.destroy();embedController=null;titleRequest?.abort();currentURI='';lastTitle='';musicPanel.querySelector('.spotify-mount').replaceChildren();musicPanel.hidden=true;showState('off');const title=document.querySelector('.track-title');if(title)title.textContent='make yourself at home.';musicButton.setAttribute('aria-expanded','false');musicButton.focus()}
async function openMusic(){if(!musicPanel.hidden)return;const token=++generation;musicPanel.hidden=false;showState('ready');musicButton.setAttribute('aria-expanded','true');musicPanel.querySelector('.music-help').textContent='loading your listening room…';try{const api=await getSpotifyAPI();if(token!==generation||musicPanel.hidden)return;const mount=document.createElement('div');musicPanel.querySelector('.spotify-mount').appendChild(mount);api.createController(mount,{uri:playlistURI,width:'100%',height:352},controller=>{if(token!==generation){controller.destroy();return}embedController=controller;controller.addListener('ready',()=>{if(token===generation){musicPanel.querySelector('.music-help').textContent='if music doesn’t start, press play here. spotify may require this extra step.';controller.play()}});controller.addListener('playback_started',e=>{if(token!==generation)return;trackTitle(e.data.playingURI)});controller.addListener('playback_update',e=>{if(token!==generation||musicPanel.hidden)return;const d=e.data;showState(d.isPaused?'paused':d.isBuffering?'buffering':'playing');if(d.playingURI)trackTitle(d.playingURI)});});}catch{if(token===generation){showState('error');musicPanel.querySelector('.music-help').textContent='spotify is unavailable here. you can open the playlist directly below.'}}}
musicButton.onclick=()=>musicPanel.hidden?openMusic():closeMusic();
musicPanel.querySelector('.music-close').onclick=closeMusic;
musicPanel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeMusic()}});
if(deckPower)deckPower.onclick=()=>{if(musicPanel.hidden){openMusic();return}if(embedController&&playbackMode==='playing'){embedController.pause()}else if(embedController&&playbackMode==='paused'){embedController.resume()}else{musicPanel.querySelector('.music-close').focus()}};
